import sys, json
d = json.load(sys.stdin)
for p, methods in d['paths'].items():
    for m, info in methods.items():
        if 'settle' in info.get('operationId', '').lower() or 'settlement' in p.lower() or 'advance' in info.get('operationId', '').lower() or 'close' in info.get('operationId', '').lower() or 'final' in info.get('operationId', '').lower():
            print(f'{m.upper()} {p} - {info.get(\"operationId\", \"\")}: {info.get(\"description\", \"\")}')
"

